'use strict';

var LexicalComposerContext = require('@lexical/react/LexicalComposerContext');
var utils = require('@lexical/utils');
var react = require('react');

/**
 * Copyright (c) Meta Platforms, Inc. and affiliates.
 *
 * This source code is licensed under the MIT license found in the
 * LICENSE file in the root directory of this source tree.
 *
 */

/**
 * Keeps the visual selection highlight on display even when the editor loses
 * focus, which is useful when interacting with toolbars or other controls
 * outside the editor. Pass `onReposition` to be notified when the highlighted
 * range elements are recomputed.
 *
 * This is a legacy plugin. When building an editor with the extension API,
 * configure {@link SelectionAlwaysOnDisplayExtension} instead.
 *
 * @returns `null`, this plugin renders no DOM of its own.
 */
function SelectionAlwaysOnDisplay({
  onReposition
}) {
  const [editor] = LexicalComposerContext.useLexicalComposerContext();
  react.useEffect(() => {
    return utils.selectionAlwaysOnDisplay(editor, onReposition);
  }, [editor, onReposition]);
  return null;
}

exports.SelectionAlwaysOnDisplay = SelectionAlwaysOnDisplay;
